/* -------------------- сид + инициализация -------------------- */
function dcSeedExtra(){
  if(typeof CHATS === 'undefined') return false;
  if(!dcExtraAllowed()) return false;
  if(CHATS.find(c=>c.id===9020)) return false; /* защита от двойного пуша */

  const all = [...DC_CHATS_X_DIRECT, ...DC_CHATS_X_GROUPS, ...DC_CHATS_X_CHANNELS];
  /* градиентная аватарка по имени — только там, где нет своей */
  all.forEach(c=>{ if(!c.avaBg && !c.avaIcon) c.avaBg = dcAvaGrad(c.name); });

  /* вставляем сразу после живого чата, живой чат — всегда №1 */
  const at = Math.min(1, CHATS.length);
  CHATS.splice(at, 0, ...all);
  return true;
}

/* --- подсказка админу: включить/выключить демо-режим прямо из консоли ---
   okoDemo(true|false). Полезно для скринкастов и превью на публичной ссылке. */
if(typeof window !== 'undefined' && !window.okoDemo){
  window.okoDemo = function(on){
    try{
      if(on === false){ localStorage.removeItem('oko-demo'); }
      else { localStorage.setItem('oko-demo','1'); }
      location.reload();
    }catch(e){}
  };
}

(function dcInitExtra(){
  try{
    dcPatchAvaHtmlExtra();
    if(dcSeedExtra()){
      /* если чат-лист уже отрисован — обновляем без ожидания */
      try{
        if(typeof renderChatList === 'function' && document.getElementById('chatList')){
          const s = document.getElementById('chatSearch');
          renderChatList(s ? s.value : '');
        }
      }catch(e){}
    }
  }catch(e){ console.warn('demo-content extra init:', e); }
})();
